public partial class BaseTest
{
        public void testCheckAddress()
        {
            var exchange = new ccxt.Exchange(new Dictionary<string, object>() {
                { "id", "sampleexchange" },
            });
            string address = "rDsbeomae4FXwgQTJp9Rs64Qg9vDiTCdBv";
            // currencies without a tag requirement pass with or without a tag
            Assert(isEqual(exchange.checkAddress(address), address));
            Assert(isEqual(exchange.checkAddress(address, "BTC"), address));
            // tag-required currencies need a tag
            Assert(isEqual(exchange.checkAddress(address, "XRP", "123456"), address));
            Assert(isEqual(exchange.checkAddress(address, "ATOM", "123456"), address));
            bool caught = false;
            try
            {
                exchange.checkAddress(address, "XRP");
            } catch(Exception error)
            {
                caught = true;
            }
            Assert(caught, "XRP without a tag should have thrown");
            caught = false;
            try
            {
                exchange.checkAddress(address, "XLM", null);
            } catch(Exception error)
            {
                caught = true;
            }
            Assert(caught, "XLM without a tag should have thrown");
            caught = false;
            try
            {
                exchange.checkAddress(null, "BTC");
            } catch(Exception error)
            {
                caught = true;
            }
            Assert(caught, "an undefined address should have thrown");
        }
}